import{_ as h,o as t,c as a,a4 as c}from"./chunks/framework.CRKgIIuH.js";const d=JSON.parse('{"title":"MODULE 0. BẮT ĐẦU Ở ĐÂY: HƯỚNG DẪN TỰ HỌC & NGUYÊN TẮC CỐT LÕI","description":"","frontmatter":{},"headers":[],"relativePath":"course/book/ch00.md","filePath":"course/book/ch00.md"}'),i={name:"course/book/ch00.md"};function o(u,n,g,r,l,e){return t(),a("div",null,[...n[0]||(n[0]=[c(`<blockquote><p><strong>Lưu ý hiển thị:</strong> sơ đồ Mermaid và/hoặc công thức được giữ nguyên dạng mã vì VitePress hiện chưa cấu hình renderer tương ứng.</p></blockquote><h1 id="module-0-bat-đau-o-đay-huong-dan-tu-hoc-nguyen-tac-cot-loi" tabindex="-1">MODULE 0. BẮT ĐẦU Ở ĐÂY: HƯỚNG DẪN TỰ HỌC &amp; NGUYÊN TẮC CỐT LÕI <a class="header-anchor" href="#module-0-bat-đau-o-đay-huong-dan-tu-hoc-nguyen-tac-cot-loi" aria-label="Permalink to &quot;MODULE 0. BẮT ĐẦU Ở ĐÂY: HƯỚNG DẪN TỰ HỌC &amp; NGUYÊN TẮC CỐT LÕI&quot;">​</a></h1><blockquote><p><strong>Tên khóa học:</strong> Quản lý dữ liệu nghiên cứu y sinh (Biomedical Research Data Management - BioRDM)<br><strong>Hình thức:</strong> Khóa học mở miễn phí, tự học theo nhịp (Free, Self-paced)<br><strong>Thời gian đọc:</strong> Khoảng 4–6 giờ đọc + quiz cho toàn bộ nội dung; khoảng 9–12 giờ nếu làm đủ lab và capstone <strong>Tác giả:</strong> TS. Hoàng Quang Huy (Đại học Bách khoa Hà Nội, iBME Lab)</p></blockquote><hr><h2 id="_1-khoa-hoc-nay-hoat-đong-nhu-the-nao" tabindex="-1">1. KHÓA HỌC NÀY HOẠT ĐỘNG NHƯ THẾ NÀO? <a class="header-anchor" href="#_1-khoa-hoc-nay-hoat-đong-nhu-the-nao" aria-label="Permalink to &quot;1. KHÓA HỌC NÀY HOẠT ĐỘNG NHƯ THẾ NÀO?&quot;">​</a></h2><p>Chào mừng bạn đến với khóa học <strong>Quản lý dữ liệu nghiên cứu y sinh (Biomedical RDM)</strong>! Khóa học này được thiết kế dành cho sinh viên kỹ thuật y sinh, công nghệ thông tin y tế, các bác sĩ lâm sàng, điều phối viên nghiên cứu (CRC/CRA) và nhà khoa học dữ liệu mong muốn làm chủ kỹ năng quản trị dữ liệu nghiên cứu chuẩn quốc tế.</p><h3 id="ba-nguyen-tac-tu-hoc" tabindex="-1">Ba nguyên tắc tự học: <a class="header-anchor" href="#ba-nguyen-tac-tu-hoc" aria-label="Permalink to &quot;Ba nguyên tắc tự học:&quot;">​</a></h3><ol><li><strong>Mở là học ngay, không cần chờ đợi:</strong> Toàn bộ 6 module lý thuyết, 6 bài lab thực hành và các câu hỏi kiểm tra đều mở sẵn. Bạn có thể học tuần tự từ M0 đến M6 (khuyến nghị) hoặc truy cập trực tiếp vào chủ đề bạn đang cần giải quyết trong nghiên cứu của mình.</li><li><strong>Không áp lực điểm số:</strong> Không có hạn nộp bài, không có điểm danh hay xếp loại qua/trượt. Các câu hỏi trắc nghiệm sau mỗi bài học cung cấp ngay đáp án đúng và phần giải thích khoa học chi tiết để bạn tự củng cố tri thức.</li><li><strong>Thực hành theo năng lực:</strong> Các bài thực hành phòng máy (Labs) được thiết kế từ mức độ cơ bản (dùng công cụ web như DMPTool, giao diện REDCap) đến nâng cao (script Python trong Lab 3–6). Bạn có thể lựa chọn làm toàn bộ hoặc bỏ qua phần lập trình nếu chỉ tập trung vào vai trò quản lý chính sách.</li></ol><hr><h2 id="_2-xuong-song-quy-trinh-workflow-7-giai-đoan" tabindex="-1">2. XƯƠNG SỐNG QUY TRÌNH: WORKFLOW 7 GIAI ĐOẠN <a class="header-anchor" href="#_2-xuong-song-quy-trinh-workflow-7-giai-đoan" aria-label="Permalink to &quot;2. XƯƠNG SỐNG QUY TRÌNH: WORKFLOW 7 GIAI ĐOẠN&quot;">​</a></h2><p>Toàn bộ nội dung khóa học vận hành xoay quanh <strong>vòng đời 7 giai đoạn</strong> của dữ liệu y sinh:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Thiết kế &amp; DMP ➔ 2. Thu thập dữ liệu (ALCOA+/EDC) ➔ 3. Làm sạch &amp; Đánh giá chất lượng</span></span>
<span class="line"><span>➔ 4. Chuẩn hóa (CDISC / FHIR / OMOP) ➔ 5. FAIR &amp; Chia sẻ kho lưu trữ</span></span>
<span class="line"><span>➔ 6. Bảo mật &amp; Pháp lý (Luật 91/2025/QH15) ➔ 7. Kết thúc: Lưu trữ dài hạn &amp; Hủy an toàn</span></span></code></pre></div><p>Quy trình này phản ánh tư duy quản trị dữ liệu chủ động: <strong>&quot;Quyết định ở thượng nguồn càng sớm thì chi phí khắc phục ở hạ nguồn càng thấp&quot;</strong>. Một bản Kế hoạch Quản lý Dữ liệu (DMP) tốt ngay từ khâu viết đề cương sẽ giúp bạn tránh được thảm họa mất dữ liệu, bị từ chối bài báo hoặc vi phạm pháp luật bảo vệ quyền riêng tư người bệnh.</p><hr><h2 id="_3-nguyen-tac-đao-đuc-quyen-rieng-tu-nguon-du-lieu-trong-khoa-hoc" tabindex="-1">3. NGUYÊN TẮC ĐẠO ĐỨC &amp; QUYỀN RIÊNG TƯ: NGUỒN DỮ LIỆU TRONG KHÓA HỌC <a class="header-anchor" href="#_3-nguyen-tac-đao-đuc-quyen-rieng-tu-nguon-du-lieu-trong-khoa-hoc" aria-label="Permalink to &quot;3. NGUYÊN TẮC ĐẠO ĐỨC &amp; QUYỀN RIÊNG TƯ: NGUỒN DỮ LIỆU TRONG KHÓA HỌC&quot;">​</a></h2><p>Trong nghiên cứu y sinh, dữ liệu luôn gắn liền với con người và sự tin tưởng của người bệnh. Khóa học tuân thủ tuyệt đối các nguyên tắc an toàn dữ liệu:</p><ul><li><strong>Không sử dụng dữ liệu cá nhân thật:</strong> Không dùng thông tin nhận dạng cá nhân hoặc dữ liệu bệnh án thật trong các bài tập và ví dụ của khóa học. Dữ liệu thực hành là <strong>dữ liệu tổng hợp (Synthetic Data)</strong> hoặc ca bệnh giả định mô phỏng.</li><li><strong>Chứng chỉ Đạo đức Nghiên cứu (CITI Program) &amp; Thỏa thuận DUA:</strong> Trong thực tế nghiên cứu, CITI/đào tạo tương tự và DUA thường được yêu cầu, tùy cơ sở và quốc gia. Ở Việt Nam, việc này cần theo quy định của hội đồng đạo đức cơ sở và yêu cầu áp dụng cho nghiên cứu cụ thể.</li></ul><hr><h2 id="_4-cach-su-dung-quiz-tu-kiem-tra-va-bai-thuc-hanh-labs" tabindex="-1">4. CÁCH SỬ DỤNG QUIZ TỰ KIỂM TRA VÀ BÀI THỰC HÀNH (LABS) <a class="header-anchor" href="#_4-cach-su-dung-quiz-tu-kiem-tra-va-bai-thuc-hanh-labs" aria-label="Permalink to &quot;4. CÁCH SỬ DỤNG QUIZ TỰ KIỂM TRA VÀ BÀI THỰC HÀNH (LABS)&quot;">​</a></h2><h3 id="cach-dung-quiz-34-cau-hoi-tu-đanh-gia" tabindex="-1">Cách dùng Quiz (34 câu hỏi tự đánh giá): <a class="header-anchor" href="#cach-dung-quiz-34-cau-hoi-tu-đanh-gia" aria-label="Permalink to &quot;Cách dùng Quiz (34 câu hỏi tự đánh giá):&quot;">​</a></h3><ul><li>Quiz 4 câu theo bài nằm ở trang quiz của từng module trên site khóa học; việc đối chiếu và tích hợp vào từng chương trong repo gốc chưa hoàn tất (<code>CONTENT_PENDING</code>).</li><li>Sau khi hoàn thành 6 module, bạn hãy làm <strong>Quiz Tổng hợp 10 câu</strong> ở trang Cuối khóa để kiểm tra sự liên kết giữa các giai đoạn trong quy trình.</li><li><strong>Mục tiêu tự đánh giá khuyến nghị:</strong> Trả lời đúng từ <strong>24/34 câu hỏi trở lên</strong>, trong đó đúng ít nhất 2 trong 3 câu đầu tiên (Q1–Q3) của bài quiz tổng hợp; không ai ghi lại kết quả.</li></ul><h3 id="cach-dung-lab-va-rubric-20" tabindex="-1">Cách dùng Lab và Rubric /20: <a class="header-anchor" href="#cach-dung-lab-va-rubric-20" aria-label="Permalink to &quot;Cách dùng Lab và Rubric /20:&quot;">​</a></h3><ul><li>Mỗi chương cung cấp 1 bài thực hành cụ thể kèm dữ liệu mẫu và các bước chi tiết.</li><li>Bảng Rubric /20 ở cuối mỗi bài lab là <strong>thước đo tự kiểm tra (Self-Checklist)</strong>; mức $\\ge 16/20$ chỉ là gợi ý để tự đối chiếu, không thay thế đánh giá năng lực trong một dự án thực tế.</li><li>Bài tập Capstone cuối khóa giúp bạn tự ghép nối toàn bộ các sản phẩm (DMP, biểu mẫu thu thập, đánh giá chất lượng, kế hoạch chia sẻ) thành một hồ sơ quản trị dữ liệu hoàn chỉnh.</li></ul><p>Hãy bắt đầu hành trình của bạn với <strong>Module 1: Tổng quan RDM, Vòng đời Dữ liệu và Kế hoạch DMP</strong>!</p>`,24)])])}const p=h(i,[["render",o]]);export{d as __pageData,p as default};
